package com.nightbeam.donutshards.transaction;
import com.nightbeam.donutshards.database.*;import com.nightbeam.donutshards.model.*;import org.junit.jupiter.api.*;import java.nio.file.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
class TransactionRepositoryTest {private Path dir;private DatabaseManager db;private TransactionRepository repo;@BeforeEach void setup()throws Exception{dir=Files.createTempDirectory("donutshards-test");db=new DatabaseManager(new DatabaseConfig(DatabaseConfig.Type.SQLITE,"test.db","",0,"","","",1,5000),dir);db.migrate();repo=new TransactionRepository(db,"test",1000);}@AfterEach void close()throws Exception{db.close();try(var files=Files.walk(dir)){files.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.deleteIfExists(p);}catch(Exception ignored){}});}}
 @Test void addsRemovesAndRejectsNegative()throws Exception{var id=UUID.randomUUID();var added=repo.mutate(id,null,100,ctx("add"));assertThat(added.success()).isTrue();assertThat(repo.balance(id)).isEqualTo(100);var removed=repo.mutate(id,null,-40,ctx("remove"));assertThat(removed.transaction().newBalance()).isEqualTo(60);assertThat(repo.mutate(id,null,-61,ctx("fail")).reason()).isEqualTo("insufficient_balance");assertThat(repo.balance(id)).isEqualTo(60);}
 @Test void transferIsAtomicAndIdempotent()throws Exception{var from=UUID.randomUUID();var to=UUID.randomUUID();repo.mutate(from,null,500,ctx("seed"));var context=ctx("transfer");var first=repo.transfer(from,to,100,250,context);var repeated=repo.transfer(from,to,100,250,context);assertThat(first.success()).isTrue();assertThat(repeated.success()).isTrue();assertThat(repo.balance(from)).isEqualTo(397);assertThat(repo.balance(to)).isEqualTo(100);}
 @Test void rejectsOverflowAndMaximum()throws Exception{var id=UUID.randomUUID();repo.mutate(id,1000L,0,ctx("set"));assertThat(repo.mutate(id,null,1,ctx("overflow")).reason()).isEqualTo("balance_limit");}
 private MutationContext ctx(String key){return new MutationContext(TransactionType.API,"test",null,key,Map.of());}}
